using MediatR;using Microsoft.AspNetCore.Mvc;using Namaa.Api.Contracts.Payments;using Namaa.Api.Extensions;using Namaa.Application.Payments.Commands.CreatePayment;using Namaa.Application.Payments.Commands.UpdatePayment;using Namaa.Application.Payments.Queries.GetPaymentById;using Namaa.Application.Payments.Queries.GetPayments;namespace Namaa.Api.Controllers;[ApiController][Route("api/payments")]public sealed class PaymentsController(ISender sender):ControllerBase{[HttpPost]public async Task<IActionResult>Create(CreatePaymentRequest request,CancellationToken cancellationToken){var result=await sender.Send(new CreatePaymentCommand(request.PaymentNumber,request.PaymentDate,request.PaymentMethod,request.Amount,request.InvoiceId,request.CustomerId,request.ReferenceNumber,request.Notes),cancellationToken);return result.IsFailure?result.ToActionResult(this):CreatedAtAction(nameof(GetById),new{id=result.Value.Id},result.Value);}[HttpGet]public async Task<IActionResult>GetAll(CancellationToken cancellationToken)=>(await sender.Send(new GetPaymentsQuery(),cancellationToken)).ToActionResult(this);[HttpGet("{id:long}")]public async Task<IActionResult>GetById(long id,CancellationToken cancellationToken)=>(await sender.Send(new GetPaymentByIdQuery(id),cancellationToken)).ToActionResult(this);[HttpPut("{id:long}")]public async Task<IActionResult>Update(long id,UpdatePaymentRequest request,CancellationToken cancellationToken)=>(await sender.Send(new UpdatePaymentCommand(id,request.PaymentDate,request.PaymentMethod,request.Amount,request.ReferenceNumber,request.Notes,request.RowVersion),cancellationToken)).ToActionResult(this);}
